"""Compact GitHub-style links, restrained colored labels, and section rules."""
from pathlib import Path
from html import escape
OUT=Path(__file__).resolve().parents[1]/'assets'
for theme in ['dark','light']:
 dark=theme=='dark';bg='#161b22' if dark else '#f6f8fa';fg='#e6edf3' if dark else '#1f2328';border='#3d444d' if dark else '#d1d9e0'
 for slug,title,col in [('oss','01 / OPEN SOURCE','#bc8cff' if dark else '#8250df'),('build','02 / SELECTED PROJECTS','#58cde8' if dark else '#087d98'),('career','03 / EXPERIENCE','#79b8ff' if dark else '#0969da'),('stack','04 / CORE STACK','#56d4a2' if dark else '#16794d')]:
  (OUT/f'section-{slug}-{theme}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" width="360" height="44" viewBox="0 0 360 44"><defs><linearGradient id="a"><stop stop-color="{col}"/><stop offset="1" stop-color="{border}" stop-opacity=".25"/></linearGradient></defs><path d="M1 9V29M1 19H8" stroke="{col}" stroke-width="1.5"/><text x="18" y="24" fill="{col}" font-size="13" font-family="Arial,sans-serif" font-weight="600" letter-spacing="1.6">{title}</text><path d="M265 19H359" stroke="url(#a)"/><path d="M351 15L359 19L351 23" fill="none" stroke="{col}"/></svg>')
 for slug,label,w in [('portfolio','Portfolio ↗',112),('linkedin','LinkedIn ↗',106),('repos','Repositories ↗',136),('prs','View merged PRs ↗',164),('background','Full background ↗',156)]:
  (OUT/f'link-{slug}-{theme}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="32"><rect x=".5" y=".5" width="{w-1}" height="31" rx="5" fill="{bg}" stroke="{border}"/><text x="12" y="21" fill="{fg}" font-family="Arial,sans-serif" font-size="12" font-weight="600">{label}</text></svg>')
 for slug,label,w,c in [('python','Python',79,'#e3b341'),('django','Django',80,'#56d4a2'),('fastapi','FastAPI',85,'#39c5cf'),('react','React',75,'#58a6ff'),('typescript','TypeScript',105,'#79b8ff'),('postgres','PostgreSQL',109,'#bc8cff'),('docker','Docker',82,'#58cde8')]:
  (OUT/f'stack-{slug}-{theme}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="28"><rect x=".5" y=".5" width="{w-1}" height="27" rx="4" fill="{bg}" stroke="{border}"/><circle cx="11" cy="14" r="2.5" fill="{c}"/><text x="20" y="18" fill="{fg}" font-size="11" font-family="Arial,sans-serif">{label}</text></svg>')
(OUT/'merged.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" width="72" height="22"><rect width="72" height="22" rx="11" fill="#8957e5"/><path d="M11 6V13Q11 16 15 16H18M11 9L17 5" stroke="white" stroke-width="1.2" fill="none"/><text x="24" y="15" fill="white" font-family="Arial,sans-serif" font-size="10">Merged</text></svg>')
